import java.util.Scanner;

public class ElectricBill {
    private String n;
    private int units;
    private double bill;

    public void accept() {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter Consumer Name: ");
        n = sc.nextLine();
        System.out.print("Enter Units Consumed: ");
        units = sc.nextInt();
    }

    public void calculate() {
        double meterRent = 150.0;
        double energyCharge = 0.0;

        if (units <= 100) {
            energyCharge = units * 1.50;
        } else if (units <= 300) {
            energyCharge = (100 * 1.50) + ((units - 100) * 2.50);
        } else {
            energyCharge = (100 * 1.50) + (200 * 2.50) + ((units - 300) * 4.00);
        }

        bill = energyCharge + meterRent;
    }

    public void print() {
        System.out.println("\n========================================");
        System.out.println("       WEST BENGAL ELECTRICITY BILL     ");
        System.out.println("========================================");
        System.out.println("Consumer Name  : " + n);
        System.out.println("Units Consumed : " + units);
        System.out.println("Meter Rent     : Rs. 150.00");
        System.out.printf("Total Amount   : Rs. %.2f\n", bill);
        System.out.println("========================================");
    }

    public static void main(String[] args) {
        ElectricBill consumer = new ElectricBill();
        consumer.accept();
        consumer.calculate();
        consumer.print();
    }
}
```

