import java.util.Scanner;

public class StudentRollSearch {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[] roll = new int[20];

        System.out.println("Enter 20 Student Roll Numbers:");
        for (int i = 0; i < 20; i++) {
            System.out.print("Roll [" + (i + 1) + "]: ");
            roll[i] = sc.nextInt();
        }

        System.out.print("\nEnter Roll Number to Search: ");
        int searchKey = sc.nextInt();

        boolean found = false;
        int foundPos = -1;
        int maxRoll = roll[0];
        int minRoll = roll[0];

        for (int i = 0; i < roll.length; i++) {
            if (roll[i] == searchKey) {
                found = true;
                foundPos = i + 1;
            }
            if (roll[i] > maxRoll) maxRoll = roll[i];
            if (roll[i] < minRoll) minRoll = roll[i];
        }

        System.out.println("\n--- Search & Statistics Results ---");
        if (found) {
            System.out.println("Roll Number found at position: " + foundPos);
        } else {
            System.out.println("Roll Number not found in record.");
        }
        System.out.println("Highest Roll Number : " + maxRoll);
        System.out.println("Lowest Roll Number  : " + minRoll);
    }
}
```

