import java.util.Scanner;

public class VowelFrequencyCounter {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter a sentence: ");
        String str = sc.nextLine().toUpperCase();

        int countA = 0, countE = 0, countI = 0, countO = 0, countU = 0;
        int totalAlphabets = 0, totalConsonants = 0;

        for (int i = 0; i < str.length(); i++) {
            char ch = str.charAt(i);
            if (Character.isLetter(ch)) {
                totalAlphabets++;
                switch (ch) {
                    case 'A': countA++; break;
                    case 'E': countE++; break;
                    case 'I': countI++; break;
                    case 'O': countO++; break;
                    case 'U': countU++; break;
                    default: totalConsonants++; break;
                }
            }
        }

        System.out.println("\n=================================");
        System.out.println("        VOWEL FREQUENCY TABLE    ");
        System.out.println("=================================");
        System.out.println("Vowel 'A' : " + countA);
        System.out.println("Vowel 'E' : " + countE);
        System.out.println("Vowel 'I' : " + countI);
        System.out.println("Vowel 'O' : " + countO);
        System.out.println("Vowel 'U' : " + countU);
        System.out.println("---------------------------------");
        System.out.println("Total Alphabets  : " + totalAlphabets);
        System.out.println("Total Consonants : " + totalConsonants);
        System.out.println("=================================");
    }
}
```

