import java.util.Scanner;

public class MatrixDiagonalSum {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int[][] mat = new int[4][4];

        System.out.println("Enter 16 elements for 4x4 Matrix:");
        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                System.out.print("Element [" + i + "][" + j + "]: ");
                mat[i][j] = sc.nextInt();
            }
        }

        System.out.println("\n--- 4x4 Matrix Display ---");
        int leftDiagSum = 0;
        int rightDiagSum = 0;

        for (int i = 0; i < 4; i++) {
            for (int j = 0; j < 4; j++) {
                System.out.print(mat[i][j] + "\t");
                if (i == j) leftDiagSum += mat[i][j];
                if (i + j == 3) rightDiagSum += mat[i][j];
            }
            System.out.println();
        }

        System.out.println("\nSum of Left Diagonal Elements  : " + leftDiagSum);
        System.out.println("Sum of Right Diagonal Elements : " + rightDiagSum);
        System.out.println("Total Diagonal Sum             : " + (leftDiagSum + rightDiagSum));
    }
}
```

