public class OverloadPolygon {
    public void polygon(int n, char ch) {
        System.out.println("\nSquare Pattern (" + n + "x" + n + "):");
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                System.out.print(ch + " ");
            }
            System.out.println();
        }
    }

    public void polygon(int x, int y) {
        System.out.println("\nRectangle Pattern (" + x + "x" + y + "):");
        for (int i = 1; i <= x; i++) {
            for (int j = 1; j <= y; j++) {
                System.out.print("@ ");
            }
            System.out.println();
        }
    }

    public void polygon() {
        System.out.println("\nTriangle Pattern (4 rows):");
        for (int i = 1; i <= 4; i++) {
            for (int j = 1; j <= i; j++) {
                System.out.print("* ");
            }
            System.out.println();
        }
    }

    public static void main(String[] args) {
        OverloadPolygon obj = new OverloadPolygon();
        obj.polygon(3, '#');
        obj.polygon(2, 5);
        obj.polygon();
    }
}
```

